function showBeforeStoryOsakaRecoveryLine(){const e=beforeStoryScene.osaka.ending,line=BEFORE_STORY_OSAKA_RECOVERY[e.recoveryLine];e.beat=0;e.speech=beforeStorySpeechTimeline(line[1]);document.getElementById('beforeStorySpeaker').textContent=line[0]==='figure'?'BLUE FIGURE':line[0]==='crown'?'UNION CROWN':'JOSIAH RICHARDS / BC-01';document.getElementById('beforeStoryLine').textContent=line[1];document.getElementById('beforeStoryCount').textContent=(e.recoveryLine+1)+' / '+BEFORE_STORY_OSAKA_RECOVERY.length;document.getElementById('beforeStoryNext').hidden=false;document.getElementById('beforeStoryNext').textContent=e.recoveryLine===BEFORE_STORY_OSAKA_RECOVERY.length-1?'BACK TO BEFORE THE STORY →':'CONTINUE →';playBeforeStoryOsakaRecoveryVoice(e.recoveryLine);}
